export function filterTitles(rows: Array<{ title: string }>, value: string) {
  const text = value.toLowerCase().trim();
  return rows.filter(row => row.title.toLowerCase().includes(text));
}
export function filterRecords(rows: Array<{ title: string }>, query: string) {
  const needle = query.toLowerCase().trim();
  return rows.filter(row => row.title.toLowerCase().includes(needle));
}
import { filterRecords } from '../search/queryIndex';
export function findVisibleRecords(rows: Array<{ title: string }>, query: string) { return filterRecords(rows, query); }
